def select_demand(corpus_df):
    fallback_ids = ['n06-r07', 'n06-r08']
    records = []
    market_demand_fields = [
        'observed_jobs',
        'pain',
        'triggers',
        'alternatives',
        'consequences',
        'outcomes',
    ]

    if corpus_df.empty:
        return pd.DataFrame(records)

    score_mask = corpus_df.get('demand_score', 0) >= 3
    fallback_mask = corpus_df.get('record_id', '').isin(fallback_ids)
    candidate_df = corpus_df[score_mask | fallback_mask]

    available_evidence_fields = [field for field in market_demand_fields if field in candidate_df.columns]
    if not available_evidence_fields:
        return pd.DataFrame(records)

    for _, row in candidate_df.iterrows():
        has_market_demand_evidence = any(bool(row.get(field, '')) for field in available_evidence_fields)
        if not has_market_demand_evidence:
            continue
        records.append({'record_id': row.get('record_id', ''), 'need': row.get('need', ''), 'demand_score': row.get('demand_score', 0), 'source_id': row.get('source_id', ''), 'source_weight': row.get('source_weight', 0)})
    return pd.DataFrame(records)
